struct Effect {
    rule_name: &'static str,
    kind: EffectKind,
    value: i64,
    multiplier: Option<&'static str>,
    requirements: &'static [Req],
}

const fn effect(
    rule_name: &'static str,
    kind: EffectKind,
    value: i64,
    multiplier: Option<&'static str>,
    requirements: &'static [Req],
) -> Effect {
    Effect {
        rule_name,
        kind,
        value,
        multiplier,
        requirements,
    }
}

